sp_widget.css:
.alert {
    margin-top: 20px;
}

.b {
    margin-top: 15px;
}

.panel-heading {
		padding: 10px 0 5px 40px;
}

.panel-body {
    padding: 40px;
}

.panel-body {
    padding: 15px;
    padding-bottom: 40px;
}

.label.upper-case {
 	text-transform: uppercase; 
}

.cell {
  	display: flex;
	align-items: center;
  	height: 70px;
  	padding: 0;
	overflow: hidden;
	word-break: break-word;
}

.row-border {
	border-bottom: 1px solid #dee5e7;
}

.th .cell {
	 	padding-bottom: 10px;
    align-items: flex-end; 
  	height: 60px;
}

.header .cell {
	font-weight: 700;
}

.contact-row:hover .cell {
  	background-color: $list-group-hover-bg;
}

.cell.flex-right {
 		justify-content: flex-end; 
		padding-right: 0rem;
}

.first-cell {
	  padding-left: 10px;
}

a#new_contact:hover, 
a#new_contact:hover i,
.panel.vdp .contact-row a:hover{
    color: $brand-primary;
}

.contact-row .label.upper-case {
	  padding: .3em .6em .2em;
  	margin-left: 4px;
}

.contact-row:hover > div {
    background-color: $breadcrumb-bg!important;
}

.label-primary,
.label-warning {
  min-width: 75px;
}

.label-primary {
    color: $label-color;
  	background-color: $brand-success
}

.label-warning {
    background-color: $label-warning-bg;
  	color: $label-color;
}

.panel-body .contact-row {
  .no-gutter > [class*='col-'] {
    padding-right:0;
    padding-left:0;
  }
}

@media (max-width: 767px){
  .cell {
	height: 50px;
    border-bottom: 1px solid #dee5e7;
  }
}

.sortorder:after {
   content: '\25b2';
 } 
 .sortorderd:after {
    content: '\25bc';
 }
.sortorder0:after {
  content: '';
 }

sp_widget.script:
(function() {
  /* populate the 'data' object */
  /* e.g., data.table = $sp.getValue('table'); */


	  var utils = new x_631631_sc_grc_co.grcPortalUtils();
    var list = utils.getImmediateTasks('sys_class_name!=sn_grc_issue');

		data.list = list;

		var searchParams = {
			table: 'planned_task',
			filter: 'sys_class_name=sn_grc_issue',
			enable_filter: true
		};
	    var coolClockOptions = {"zone": "America/Los_Angeles","title": "San Diego, CA"}


		data.filterBreadcrumbs = $sp.getWidget('widget-filter-breadcrumbs', searchParams);

	//gs.addInfoMessage('fbc: ' + Object.values(data.filterBreadcrumbs));

})();
